SET search_path = public, extensions;

-- Seeds 4 orphaned sandbox-tier LPM capstones (OE-SANDBOX-LPM-000001..000004) as
-- nested draft Projects under bio-core-lpm-synth / interdisciplinary-lpm-synth.
-- These never merged into bio-core-k12/oe-interdisciplinary-k12's own main branch
-- and never made it into 092/139's content seed; both source repos were retired
-- (GitHub deleted) before this content had anywhere else to go. Generated by
-- scripts/generate_sandbox_capstones_seed.py, not hand-typed.
--
-- Per RFC-0010/migration-015 precedent, nothing is auto-inherited from the parent
-- Project Space: each nested Project declares its own schema_elements for any
-- concept it introduces, and tags cross-referenced trunk concepts by their real
-- ConceptBase id in each data object's own content JSONB (matching 092's own
-- convention), without a formal FK into the parent's schema_elements rows.
--
-- Idempotent: fixed uuid5 ids throughout, ON CONFLICT DO NOTHING / unique
-- constraints on every insert -- safe to re-apply.

DO $MIGRATION$
DECLARE
  v_bio_parent UUID;
  v_inter_parent UUID;
BEGIN

  SELECT id INTO v_bio_parent FROM projects WHERE slug = 'bio-core-lpm-synth';
  SELECT id INTO v_inter_parent FROM projects WHERE slug = 'interdisciplinary-lpm-synth';
  IF v_bio_parent IS NULL OR v_inter_parent IS NULL THEN
    RAISE EXCEPTION 'Expected both bio-core-lpm-synth and interdisciplinary-lpm-synth to already exist';
  END IF;

  -- ==========================================================================
  -- Projects: 4 nested, draft, designed-thought-experiment sub-projects
  -- ==========================================================================
  INSERT INTO projects (id, slug, name, description, status, epistemic_status, epistemic_status_note, hosting_mode, maturity, parent_project_id, focus_type, theme_tags, working_languages)
  VALUES
  ($J$a1e2ffa1-5176-53f6-8c96-fa80847ac7a9$J$, $J$bio-core-human-lineage-capstone$J$, $J$Human Lineage: Genetics and Paleoanthropology Capstone$J$, $J$9-12 capstone (OE-SANDBOX-STRAND-000001/RFC-0010) treating human evolutionary history with exactly the same evidentiary/causal toolkit as the parent Space's Speciation and Diversity of Life strand -- phylogeny, population genetics, ancient DNA -- applied specifically to the hominin lineage, with no agency, intention, or culture vocabulary introduced anywhere. Includes a guided-path trajectory variant (RFC-0009) for students without reliable prior exposure to the parent strands' population-genetic reasoning.$J$, 'active', 'designed-thought-experiment', $J$Sandbox-tier LPM fork (ConceptBase RFC-0010), never merged into its source repo's own main branch and never field-tested. Migrated here only because its source repo (bio-core-k12) was retired (GitHub deleted) after the repo's own real/flagship content was already ported to this Project Space's parent in migrations 092/139 -- this nested Project preserves the one piece of that repo's work that wasn't already somewhere else. Self-labeled designed-thought-experiment throughout, same as its parent; never promoted or reviewed by a subject-matter expert.$J$, 'hosted', 'draft', v_bio_parent, 'thematic', ARRAY[$J$human-evolution$J$,$J$paleoanthropology$J$]::TEXT[], ARRAY['en']::TEXT[]),
  ($J$9ae75e2a-c3ac-5a9d-9ce8-f0c743706ee3$J$, $J$bio-core-human-lineage-k12$J$, $J$Human Lineage: Genetics and Paleoanthropology (K-12)$J$, $J$Full K-2 -> 9-12 strand (OE-SANDBOX-STRAND-000004/RFC-0010) on human evolutionary genetics and paleoanthropology, strictly non-agentic throughout, mirroring the parent Space's Speciation and Diversity of Life strand's four-substrand shape and spreading the hominin lineage as the worked example across all four grade bands rather than concentrating it in one 9-12 capstone. Includes a guided-path trajectory variant (RFC-0009) at 6-8, the grade band Branch, Reid & Plutzer (2021) document as having the most inconsistent prior evolution coverage in US schools.$J$, 'active', 'designed-thought-experiment', $J$Sandbox-tier LPM fork (ConceptBase RFC-0010), never merged into its source repo's own main branch and never field-tested. Migrated here only because its source repo (bio-core-k12) was retired (GitHub deleted) after the repo's own real/flagship content was already ported to this Project Space's parent in migrations 092/139 -- this nested Project preserves the one piece of that repo's work that wasn't already somewhere else. Self-labeled designed-thought-experiment throughout, same as its parent; never promoted or reviewed by a subject-matter expert.$J$, 'hosted', 'draft', v_bio_parent, 'thematic', ARRAY[$J$human-evolution$J$,$J$paleoanthropology$J$]::TEXT[], ARRAY['en']::TEXT[]),
  ($J$e94a08ff-8064-5f7c-b20a-67278aa730a4$J$, $J$interdisciplinary-evo-anthro-capstone$J$, $J$Evo-Anthro Capstone$J$, $J$9-12 capstone (OE-SANDBOX-STRAND-000010/RFC-0010) organized around seven fields of evolutionary anthropology (archaeogenetics, comparative cultural psychology, evolutionary genetics, human behavioral ecology, human origins/paleoanthropology, linguistic and cultural evolution, and primate behavior and evolution), as a genuine cross-vocabulary integration of BIO-CORE and OE-INTERDISCIPLINARY concepts rather than a single-discipline treatment. Includes a real, generated (unreviewed, unpiloted) comparative-cognition assessment item bank. Content areas are informed by the broadly-practiced public research of these seven fields as of 2026, including at the Max Planck Institute for Evolutionary Anthropology, with which OpenEvo is glad to be affiliated -- not a review or endorsement by any individual institution or researcher. Trunk Strand 4 (Evidence for Human Origins) now carries the general-concepts version of this same territory at permanent tier; this capstone's remaining distinct value is as a 9-12 synthesis/application experience across trunk Strands 1-4, not a second copy of that content. Includes a guided-path trajectory variant (RFC-0009).$J$, 'active', 'designed-thought-experiment', $J$Sandbox-tier LPM fork (ConceptBase RFC-0010), never merged into its source repo's own main branch and never field-tested. Migrated here only because its source repo (oe-interdisciplinary-k12) was retired (GitHub deleted) after the repo's own real/flagship content was already ported to this Project Space's parent in migrations 092/139 -- this nested Project preserves the one piece of that repo's work that wasn't already somewhere else. Self-labeled designed-thought-experiment throughout, same as its parent; never promoted or reviewed by a subject-matter expert.$J$, 'hosted', 'draft', v_inter_parent, 'thematic', ARRAY[$J$evolutionary-anthropology$J$,$J$human-origins$J$]::TEXT[], ARRAY['en']::TEXT[]),
  ($J$ab9d4860-1916-5595-89c2-720404e1d83d$J$, $J$interdisciplinary-machine-culture-coevolution$J$, $J$Machine Culture and Human-AI Coevolution Capstone$J$, $J$9-12 capstone (OE-SANDBOX-STRAND-000013/RFC-0010) treating AI systems as potential participants in cultural evolution's variation/transmission/selection dynamics (Brinkmann et al. 2023, 'Machine culture,' Nature Human Behaviour), not merely as tools culture passes through -- grounded in a real, checkable research citation (co-authored by Richard McElreath, also central to the Evo-Anthro Capstone sibling sub-project, a genuine cross-institution bridge rather than a forced connection). Reinforces the parent Space's Selection and Innovation, Agency and Niche Construction, and Culture/Technology/Collective Intelligence/Distributed Cognition strands throughout. Includes a guided-path trajectory variant (RFC-0009).$J$, 'active', 'designed-thought-experiment', $J$Sandbox-tier LPM fork (ConceptBase RFC-0010), never merged into its source repo's own main branch and never field-tested. Migrated here only because its source repo (oe-interdisciplinary-k12) was retired (GitHub deleted) after the repo's own real/flagship content was already ported to this Project Space's parent in migrations 092/139 -- this nested Project preserves the one piece of that repo's work that wasn't already somewhere else. Self-labeled designed-thought-experiment throughout, same as its parent; never promoted or reviewed by a subject-matter expert.$J$, 'hosted', 'draft', v_inter_parent, 'thematic', ARRAY[$J$machine-culture$J$,$J$human-ai-coevolution$J$]::TEXT[], ARRAY['en']::TEXT[]);

  INSERT INTO project_base_links (project_id, base_repo, can_import, can_propose_pr)
  VALUES
  ($J$a1e2ffa1-5176-53f6-8c96-fa80847ac7a9$J$, 'conceptbase', TRUE, FALSE),
  ($J$9ae75e2a-c3ac-5a9d-9ce8-f0c743706ee3$J$, 'conceptbase', TRUE, FALSE),
  ($J$e94a08ff-8064-5f7c-b20a-67278aa730a4$J$, 'conceptbase', TRUE, FALSE),
  ($J$ab9d4860-1916-5595-89c2-720404e1d83d$J$, 'conceptbase', TRUE, FALSE)
  ON CONFLICT (project_id, base_repo) DO NOTHING;

  INSERT INTO project_source_declarations (project_id, source_name, format, license_or_rights_note, url)
  SELECT * FROM (VALUES
    ($J$a1e2ffa1-5176-53f6-8c96-fa80847ac7a9$J$::UUID, $J$bio-core-k12 (GitHub repo, retired)$J$, $J$YAML (ConceptBase oe:Strand schema, sandbox tier)$J$, $J$CC-BY-NC-SA-4.0. Branch sandbox/human-evolution-capstone, never merged, never previously migrated. Moved here 2026-10-21 after the source repo was retired.$J$, $J$https://github.com/openevo-ccs/bio-core-k12 (deleted)$J$),
    ($J$9ae75e2a-c3ac-5a9d-9ce8-f0c743706ee3$J$::UUID, $J$bio-core-k12 (GitHub repo, retired)$J$, $J$YAML (ConceptBase oe:Strand schema, sandbox tier)$J$, $J$CC-BY-NC-SA-4.0. Branch sandbox/human-evolution-k12-strand, never merged, never previously migrated. Moved here 2026-10-21 after the source repo was retired.$J$, $J$https://github.com/openevo-ccs/bio-core-k12 (deleted)$J$),
    ($J$e94a08ff-8064-5f7c-b20a-67278aa730a4$J$::UUID, $J$oe-interdisciplinary-k12 (GitHub repo, retired)$J$, $J$YAML (ConceptBase oe:Strand schema, sandbox tier) + JSON (assessment item bank)$J$, $J$CC-BY-NC-SA-4.0. Branches sandbox/eva-capstone and sandbox/gwdg-comparative-cognition-assessment, never merged, never previously migrated. Item bank is gwdg-dataset-forge output, self-labeled AI-DRAFT-UNPILOTED -- status carried forward unchanged, not reviewed or piloted. Moved here 2026-10-21 after the source repo was retired.$J$, $J$https://github.com/openevo-ccs/interdisciplinary-k12 (deleted)$J$),
    ($J$ab9d4860-1916-5595-89c2-720404e1d83d$J$::UUID, $J$oe-interdisciplinary-k12 (GitHub repo, retired)$J$, $J$YAML (ConceptBase oe:Strand schema, sandbox tier)$J$, $J$CC-BY-NC-SA-4.0. Branch sandbox/machine-culture-coevolution, never merged, never previously migrated. Moved here 2026-10-21 after the source repo was retired.$J$, $J$https://github.com/openevo-ccs/interdisciplinary-k12 (deleted)$J$)
  ) AS v(project_id, source_name, format, license_or_rights_note, url)
  WHERE NOT EXISTS (
    SELECT 1 FROM project_source_declarations psd
    WHERE psd.project_id = v.project_id AND psd.source_name = v.source_name
  );

  -- ==========================================================================
  -- New sandbox concepts, scoped to whichever project introduces them
  -- ==========================================================================
  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, parent_id, metadata, status)
  VALUES
  ($J$16e94a62-8dba-5c14-a2da-38266c0d2a74$J$, $J$a1e2ffa1-5176-53f6-8c96-fa80847ac7a9$J$, 'concept', $J$Hominin$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "vocabulary": "BIO-CORE-v1.0.0", "definition": "A member of the taxonomic group (tribe Hominini) comprising modern humans, extinct human species, and their immediate fossil ancestors since the divergence from the lineage leading to chimpanzees -- a strictly taxonomic/phylogenetic category, not an agency- or intentionality-bearing one."}$J$::jsonb, 'accepted'),
  ($J$2bfdde2f-c37c-590f-8428-62beee5c63f2$J$, $J$a1e2ffa1-5176-53f6-8c96-fa80847ac7a9$J$, 'concept', $J$Ancient DNA$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "vocabulary": "BIO-CORE-v1.0.0", "definition": "Genetic material recovered and sequenced from historical or fossil remains, enabling direct observation of genetic variation and population history at past points in time rather than inferring it solely from present-day populations."}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

