  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, parent_id, metadata, status)
  VALUES
  ($J$889fd8b8-098f-5aca-8873-9db92c9f2792$J$, $J$e94a08ff-8064-5f7c-b20a-67278aa730a4$J$, 'concept', $J$Language Evolution$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000003", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The process by which languages change, diversify, and descend from common ancestral languages over time, through the same general transmission-with-variation dynamics that shape other cultural traits."}$J$::jsonb, 'accepted'),
  ($J$f2ace86f-cdf1-586d-9b46-45632eb4770f$J$, $J$e94a08ff-8064-5f7c-b20a-67278aa730a4$J$, 'concept', $J$Comparative Cognition$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000004", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The study of cognitive capacities (perception, memory, problem-solving, social learning) across species, used to identify which capacities are shared through common ancestry, which evolved independently, and which are distinctively elaborated in a given lineage."}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, parent_id, metadata, status)
  VALUES
  ($J$89d6c106-5414-5666-9471-002e5cce2711$J$, $J$ab9d4860-1916-5595-89c2-720404e1d83d$J$, 'concept', $J$Machine Culture$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000005", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Culture that is mediated or generated by machines -- cases where AI systems shape, participate in, or themselves undergo the variation, transmission, and selection dynamics that define cultural evolution, rather than machines being only passive tools culture is transmitted through."}$J$::jsonb, 'accepted'),
  ($J$1d288d80-cb5f-5b56-89ae-3da2975900ba$J$, $J$ab9d4860-1916-5595-89c2-720404e1d83d$J$, 'concept', $J$Hybrid Social Learning$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000006", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Social learning processes that span human and artificial agents jointly -- humans learning from AI-generated content or behavior, AI systems trained on human-generated content or behavior, and the resulting feedback loop between the two -- rather than social learning occurring within a single-species population."}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

  -- ==========================================================================
  -- bio-core-human-lineage-capstone: 1 strand, 1 substrand + trajectory variant
  -- ==========================================================================
  -- Strand + 1 substrand(s): Human Lineage: Genetics and Paleoanthropology Capstone
  INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ($J$473a35be-5daa-56a8-9937-d4823a1eaf84$J$, 'strand', $J$Human Lineage: Genetics and Paleoanthropology Capstone$J$, $J$Capstone treatment of human evolutionary history using exactly the same evidentiary and causal toolkit as the Speciation and Diversity of Life strand (phylogeny, common ancestry, population genetics, extinction) applied to the hominin lineage specifically. Reinforces Variation and Inheritance's Alle$J$, $J$9-12$J$, $J$Biology$J$, $J${"description": "Capstone treatment of human evolutionary history using exactly the same evidentiary and causal toolkit as the Speciation and Diversity of Life strand (phylogeny, common ancestry, population genetics, extinction) applied to the hominin lineage specifically. Reinforces Variation and Inheritance's Allele/Population/Mutation and Natural Selection and Adaptation's Selection Pressure/Drift throughout, rather than introducing a separate explanatory framework for human evolution -- the central design commitment of this capstone.", "relations": {"foundationalTo": ["OE-STRAND-bio-core-k12-speciation-diversity"]}, "associatedDomains": ["Biology"]}$J$::jsonb, 'accepted'),
  ($J$64cd6496-2526-5a81-bb0e-6f95a2dfb264$J$, 'substrand', $J$Evidence for the Hominin Lineage$J$, NULL, $J$9-12$J$, $J$Biology$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "label": "Ancient DNA", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-phylogeny", "label": "Phylogeny", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-common-ancestor", "label": "Common Ancestor", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-population", "label": "Population", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-drift", "label": "Drift", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-selection-pressure", "label": "Selection Pressure", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-extinction", "label": "Extinction", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Constructs a hominin phylogeny from published genomic and morphological data and justifies each branch point's placement using the same evidentiary standards applied to any other lineage in the Speciation and Diversity of Life strand.", "Interprets an ancient-DNA admixture estimate (e.g., Neanderthal ancestry proportion in present-day human populations) as evidence of historical gene flow between diverged populations, without inferring intent or purpose on the part of any population.", "Distinguishes what a fossil (morphological) data point contributes to a hominin phylogeny from what an ancient-DNA (genomic) data point contributes, and explains why converging evidence from both increases confidence in a proposed relationship.", "Explains a documented shift in hominin population genetic variation (e.g., a bottleneck or founder event associated with a migration) using drift and selection pressure as the same population-genetic mechanisms already used to explain non-human population history in Natural Selection and Adaptation.", "Evaluates a claim about a specific hominin species' extinction using multiple independent lines of fossil and genetic evidence, consistent with the Speciation and Diversity of Life strand's 9-12 performance indicator for non-human extinction claims."], "contextAssumption": ["rich-scaffolding"], "trajectoryVariants": [{"label": "Evidence for the Hominin Lineage (Guided Path)", "contextAssumption": ["minimal-prior-exposure"], "concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "label": "Ancient DNA", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-phylogeny", "label": "Phylogeny", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-common-ancestor", "label": "Common Ancestor", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Given a pre-built hominin phylogeny, identifies which branches represent more closely related groups and explains what 'more closely related' means in terms of shared ancestry.", "Given a worked example of an ancient-DNA admixture estimate, explains in plain terms what the percentage represents (shared genetic ancestry from a past population) before attempting to interpret a new example independently.", "Compares a fossil-only account and a genomic-only account of the same hominin relationship, with guided support, to see that independent evidence types can point to the same conclusion."]}]}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

