  -- ==========================================================================
  -- bio-core-human-lineage-k12: 1 strand, 4 substrands (one with a variant)
  -- ==========================================================================
  -- Strand + 4 substrand(s): Human Lineage: Genetics and Paleoanthropology (K-12)
  INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ($J$62629160-0d3e-5f84-8767-2f8b7c6c00d4$J$, 'strand', $J$Human Lineage: Genetics and Paleoanthropology (K-12)$J$, $J$Macroevolutionary strand parallel to Speciation and Diversity of Life, applying the same phylogeny/population-genetics/ancient-DNA toolkit specifically to the hominin lineage, spread and reinforced across all four grade bands rather than concentrated in one 9-12 capstone. Depends on Variation and In$J$, $J$K-12 (spans all bands via substrands)$J$, $J$Biology$J$, $J${"description": "Macroevolutionary strand parallel to Speciation and Diversity of Life, applying the same phylogeny/population-genetics/ancient-DNA toolkit specifically to the hominin lineage, spread and reinforced across all four grade bands rather than concentrated in one 9-12 capstone. Depends on Variation and Inheritance (population, allele) and Natural Selection and Adaptation (natural selection, selection pressure, drift) exactly as Speciation and Diversity of Life does.", "relations": {"foundationalTo": ["OE-STRAND-bio-core-k12-speciation-diversity"]}, "associatedDomains": ["Biology"]}$J$::jsonb, 'accepted'),
  ($J$dd04cc3b-0c64-5eb0-a57d-2bf65b8f60f6$J$, 'substrand', $J$Long Ago, Different Kinds of People-Like Living Things$J$, NULL, $J$K-2$J$, $J$Biology$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-extinction", "label": "Extinction", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Recognizes that scientists study very old bones and teeth to learn about kinds of people-like living things that existed long ago and are not around today.", "Sorts pictures of a present-day human and an old fossil skull into 'living now' and 'lived long ago, no longer around,' the same way a present-day animal and a dinosaur fossil would be sorted."]}$J$::jsonb, 'accepted'),
  ($J$0af1447f-e97d-55fb-a486-3a4670b3fc72$J$, 'substrand', $J$Humans Today and Related Kinds from the Past$J$, NULL, $J$3-5$J$, $J$Biology$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-common-ancestor", "label": "Common Ancestor", "emphasis": "primary", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-species", "label": "Species", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Describes present-day humans as one species among several related 'hominin' kinds that existed at different times in the past.", "Uses a simple diagram to show that present-day humans and an extinct hominin kind (e.g. Neanderthals) share an ancestor further back in time, the same way the Speciation and Diversity of Life strand's 3-5 substrand does for any two other species."]}$J$::jsonb, 'accepted'),
  ($J$a4bbd92b-da48-5253-aafb-6f88ff79c5f1$J$, 'substrand', $J$How Scientists Study Human Origins$J$, NULL, $J$6-8$J$, $J$Biology$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "label": "Ancient DNA", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-phylogeny", "label": "Phylogeny", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-population", "label": "Population", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-mutation", "label": "Mutation", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Explains that scientists study human origins using two independent kinds of evidence -- fossils (shape, structure) and ancient DNA (genetic sequence) -- and that agreement between the two increases confidence in a conclusion.", "Reads a simple hominin phylogenetic tree and identifies which two labeled groups are more closely related, using the same tree-reading skill the Speciation and Diversity of Life strand's 6-8 substrand teaches for any other lineage.", "Explains that new mutations arising in a population, not any individual's intention or effort, are the ultimate source of the genetic differences later found between separated human populations."], "contextAssumption": ["rich-scaffolding"], "trajectoryVariants": [{"label": "How Scientists Study Human Origins (Guided Path)", "contextAssumption": ["minimal-prior-exposure"], "concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "label": "Ancient DNA", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-phylogeny", "label": "Phylogeny", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Given a short description of what a fossil is and what DNA is, explains in one's own words why finding the same answer from both is more convincing than either alone.", "With guidance, labels a simple two-branch phylogenetic tree to show which of two hominin groups shared a more recent common ancestor, before attempting a tree with more than two branches independently."]}]}$J$::jsonb, 'accepted'),
  ($J$a88878d8-2daa-5ee5-b3b5-c9cbf9045cae$J$, 'substrand', $J$Population Genetics of Modern Human Variation$J$, NULL, $J$9-12$J$, $J$Biology$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "label": "Ancient DNA", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-population", "label": "Population", "emphasis": "primary", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-drift", "label": "Drift", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-selection-pressure", "label": "Selection Pressure", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-bio-core-mutation", "label": "Mutation", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "reinforcing", "new_sandbox_concept": true}], "performanceIndicators": ["Explains present-day human genetic variation across geographic regions as the product of population history (migration, drift, founder effects) and, in some cases, selection pressure acting on specific alleles -- not as evidence of categorically distinct underlying types.", "Evaluates a specific published claim about a selection-pressure-driven allele frequency change in a human population (e.g. an allele associated with a dietary or environmental adaptation) against the same standard of evidence the Natural Selection and Adaptation strand's 9-12 performance indicator applies to non-human examples.", "Distinguishes a population-genetic explanation of human variation (allele frequencies differing gradually and continuously across populations) from a discrete-types account, using ancient-DNA evidence of historical admixture between populations as a concrete counterexample to the latter."]}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

