  -- ==========================================================================
  -- interdisciplinary-evo-anthro-capstone: 1 strand, 1 substrand + trajectory variant
  -- ==========================================================================
  -- Strand + 1 substrand(s): Evo-Anthro Capstone
  INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ($J$f1ecd05c-a0d4-5259-a91d-72182ca56999$J$, 'strand', $J$Evo-Anthro Capstone$J$, $J$Capstone Strand demonstrating that the Agency/Niche Construction and Culture/Technology/Collective Intelligence strands' cross-domain concepts (Selection, Agency, Niche Construction, Culture, Transmission) are not an in-house invention but map onto seven real, active fields of evolutionary-anthropol$J$, $J$9-12$J$, $J$Biology, Social Studies, Computer Science$J$, $J${"description": "Capstone Strand demonstrating that the Agency/Niche Construction and Culture/Technology/Collective Intelligence strands' cross-domain concepts (Selection, Agency, Niche Construction, Culture, Transmission) are not an in-house invention but map onto seven real, active fields of evolutionary-anthropological research: archaeogenetics, comparative cultural psychology, evolutionary genetics, human behavioral ecology, human origins/paleoanthropology, linguistic and cultural evolution, and primate behavior and evolution. Content areas informed by the public research of these seven fields as broadly practiced as of 2026, including at the Max Planck Institute for Evolutionary Anthropology (Leipzig) -- not a review or endorsement by any individual institution or researcher, and not organized around any one institution's department structure. See https://www.eva.mpg.de/.", "relations": {"foundationalTo": ["OE-STRAND-oe-interdisciplinary-k12-agency-development-niche", "OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective"]}, "associatedDomains": ["Biology", "Social Studies", "Computer Science"]}$J$::jsonb, 'accepted'),
  ($J$404cff2f-dc74-5bd1-89da-76abda93d6c5$J$, 'substrand', $J$Seven Fields, One Question: How Did Humans Become Human?$J$, NULL, $J$9-12$J$, $J$Biology, Social Studies, Computer Science$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000003", "label": "Language Evolution", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000004", "label": "Comparative Cognition", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-agency", "label": "Agency", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-niche-construction", "label": "Niche Construction", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-culture", "label": "Culture", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-cooperation", "label": "Cooperation", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-transmission", "label": "Transmission", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-selection", "label": "Selection", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "reinforcing", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000002", "label": "Ancient DNA", "emphasis": "reinforcing", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-bio-core-phylogeny", "label": "Phylogeny", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["[Evolutionary Genetics / Archaeogenetics] Analyzes a real ancient-DNA finding (e.g. evidence of Neanderthal or Denisovan admixture in present-day human populations) as a case where genetic evidence and cultural/behavioral inference must be evaluated against independent lines of evidence, connecting to Selection and the BIO-CORE Ancient DNA concept.", "[Human Origins] Interprets hominin fossil evidence (skeletal morphology) as evidence about behavior -- e.g., what hand or foot bone structure implies about tool use or locomotion -- distinguishing what the fossil record can and cannot directly tell us about behavior versus what requires additional inference.", "[Language Evolution] Constructs a simple language family tree from shared and divergent linguistic features and compares the method directly to constructing a biological phylogeny (BIO-CORE's Phylogeny concept), identifying what is genuinely analogous (branching, common ancestry, gradual divergence) and what is not (mechanism of transmission -- biological inheritance vs. social learning).", "[Behavioral Ecology] Explains a documented human behavioral pattern (e.g. a foraging or resource-sharing strategy in a specific population) as a response shaped by ecological and social conditions acting on the population over time -- using Agency in its deflationary sense (a capacity to regulate behavior toward a goal-state, without requiring conscious intention or deliberate planning by any individual), consistent with the Agency/Niche Construction strand's own restatement rather than a more mentalistic 'act intentionally' phrasing.", "[Comparative Cognition] Compares a specific cognitive or social capacity (e.g. cooperative problem-solving, delayed gratification, or social learning) across a non-human primate species, young children from more than one cultural context, and adult humans, identifying which differences appear species-general and which appear culturally variable -- directly reinforcing Development and Culture.", "Explains how human technological and cultural niche construction documented across multiple evolutionary-anthropology research fields -- genetic adaptation to agricultural diets, language diversification following migration, culturally transmitted tool traditions -- jointly shaped, and were shaped by, hominin population history, without treating any one field's evidence as sufficient on its own."], "contextAssumption": ["rich-scaffolding"], "trajectoryVariants": [{"label": "Seven Fields, One Question (Guided Path)", "contextAssumption": ["minimal-prior-exposure"], "concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000003", "label": "Language Evolution", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-agency", "label": "Agency", "emphasis": "primary", "new_sandbox_concept": false}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000001", "label": "Hominin", "emphasis": "reinforcing", "new_sandbox_concept": true}], "performanceIndicators": ["Before analyzing any case, is given an explicit working definition of Agency as used in this capstone ('a capacity to regulate behavior toward a goal-state, without requiring conscious intention') and practices applying it to a simple, pre-worked example (e.g. an ant colony's foraging behavior) before applying it to a human case.", "Given a short, guided explanation of what a language family tree shows, identifies which of two languages is more closely related to a third, before constructing a tree independently."]}]}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

