  -- ==========================================================================
  -- interdisciplinary-machine-culture-coevolution: 1 strand, 1 substrand + variant
  -- ==========================================================================
  -- Strand + 1 substrand(s): Machine Culture and Human-AI Coevolution Capstone
  INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ($J$c95cc82a-3cb5-594c-a086-85ece959706c$J$, 'strand', $J$Machine Culture and Human-AI Coevolution Capstone$J$, $J$Capstone Strand treating AI systems as potential participants in cultural evolution's variation/transmission/selection dynamics (Brinkmann, L., Baumann, F., Bonnefon, J.F., Derex, M., Muller, T.F., Nussberger, A.M., Czaplicka, A., Acerbi, A., Griffiths, T.L., Henrich, J., Leibo, J.Z., McElreath, R.,$J$, $J$9-12$J$, $J$Computer Science, Social Studies, Biology$J$, $J${"description": "Capstone Strand treating AI systems as potential participants in cultural evolution's variation/transmission/selection dynamics (Brinkmann, L., Baumann, F., Bonnefon, J.F., Derex, M., Muller, T.F., Nussberger, A.M., Czaplicka, A., Acerbi, A., Griffiths, T.L., Henrich, J., Leibo, J.Z., McElreath, R., Oudeyer, P.Y., Stray, J., & Rahwan, I. (2023). 'Machine culture.' Nature Human Behaviour, 7(11), 1855-1868), not merely as tools culture passes through. Reinforces Selection and Innovation, Agency and Niche Construction, and Culture, Technology, Collective Intelligence, and Distributed Cognition throughout, with the AI/culture claim grounded in a real, checkable research citation instead of a parenthetical example.", "relations": {"foundationalTo": ["OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective"]}, "associatedDomains": ["Computer Science", "Social Studies", "Biology"]}$J$::jsonb, 'accepted'),
  ($J$692b50d9-9bb1-5cdd-8ad8-5e76bb52c551$J$, 'substrand', $J$AI Systems as Participants in Cultural Evolution$J$, NULL, $J$9-12$J$, $J$Computer Science, Social Studies$J$, $J${"concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000005", "label": "Machine Culture", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-SANDBOX-CONCEPT-000006", "label": "Hybrid Social Learning", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-collective-intelligence", "label": "Collective Intelligence", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-distributed-cognition", "label": "Distributed Cognition", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-technology", "label": "Technology", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-selection", "label": "Selection", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-innovation", "label": "Innovation", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-agency", "label": "Agency", "emphasis": "reinforcing", "new_sandbox_concept": false}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-niche-construction", "label": "Niche Construction", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Explains, citing Brinkmann et al. (2023) 'Machine culture,' the difference between AI as a passive channel culture is transmitted through (e.g. a printing press) and AI as an active participant that itself shapes variation, transmission, or selection among cultural variants (e.g. a recommendation system whose outputs change what content gets created next, which then retrains the system).", "Analyzes a real or realistic case of a human-AI feedback loop (e.g. a language model trained partly on text that earlier language models helped generate) using Selection and Innovation: which step introduces variation, and which step is a selection-like filtering process, and who or what is doing the filtering.", "Distinguishes a reinforcement-learning framing (trial-and-error narrowing toward better-performing actions within one training run) from Selection as a population-level, cross-generational process, using this distinction explicitly rather than leaving it implicit.", "Evaluates a case where a designed AI system produces emergent, non-designed collective effects on a population's shared information environment -- e.g. a recommendation algorithm whose aggregate effects on public discourse were not individually designed.", "[Hybrid Social Learning] Analyzes a case of humans and an AI tutoring or recommendation system jointly shaping each other's subsequent behavior over repeated interactions, using Distributed Cognition to describe how the resulting knowledge/behavior is not fully located in either the human or the system alone."], "contextAssumption": ["rich-scaffolding"], "trajectoryVariants": [{"label": "AI Systems as Participants in Cultural Evolution (Guided Path)", "contextAssumption": ["minimal-prior-exposure"], "concepts": [{"conceptbase_id": "OE-SANDBOX-CONCEPT-000005", "label": "Machine Culture", "emphasis": "primary", "new_sandbox_concept": true}, {"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-selection", "label": "Selection", "emphasis": "reinforcing", "new_sandbox_concept": false}], "performanceIndicators": ["Given a short, concrete walkthrough of one human-AI feedback loop example (e.g. a music-recommendation app), identifies in guided discussion where 'something new is introduced' and where 'something gets favored or filtered' happen in the loop, before analyzing a second example independently.", "Given a reinforcement-learning framing explained in plain terms first, compares it to a single labeled example of biological or cultural Selection already covered, rather than being asked to derive the distinction unaided."]}]}$J$::jsonb, 'accepted')
  ON CONFLICT (id) DO NOTHING;

